#include <future>
#include <iostream>
#include <string>
int main() {
    auto first = std::async(std::launch::async, [word = std::string("red")] {
        return word.size();
    });
    auto second = std::async(std::launch::async, [word = std::string("blue")] {
        return word.size();
    });
    const auto a = first.get();
    const auto b = second.get();
    std::cout << "first=" << a << " second=" << b << " total=" << a+b << '\n';
}

#include <algorithm>
#include <array>
#include <iostream>
#include <string>
int main() {
    // Serialized enumeration of abstract activity steps.
    std::array<char,5> order{'A','A','A','B','B'};
    unsigned count = 0;
    std::string first, last;
    do {
        const std::string trace(order.begin(), order.end());
        if (count == 0) first = trace;
        last = trace;
        ++count;
    } while (std::next_permutation(order.begin(), order.end()));
    std::cout << "schedules=" << count << '\n';
    std::cout << "first=" << first << " last=" << last << '\n';
}
